fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // Ensure arrays have the same length
    assert_eq!(arr1.len(), arr2.len(), "Arrays must have equal length");
    
    // Perform element-wise division
    arr1.iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a / b)
        .collect()
}